  const persist=()=>sessionStorage.setItem(KEY,JSON.stringify(state()));
  const titles={mine:'我的',profile:'个人信息',orders:'我的订单',order:'订单详情',needs:'我的需求',favorites:'我的收藏',messages:'消息',coupons:'我的优惠券',identity:'身份验证',access:'入仓指引',renew:'续租',exit:'退租与验仓',deposit:'押金进度',invoice:'发票与付款记录',transport:'运输需求',referral:'推荐有礼',support:'联系顾问',brand:'关于迷你考拉'};
  const statusName={pending:'待支付',paid_simulated:'已付款',payment_failed:'支付失败',cancelled:'已取消',expired:'已过期',invalidated:'已失效',CLAIMED:'可使用',APPLIED:'已选择',LOCKED:'待支付订单已锁定',REDEEMED:'已使用',INVALID:'已失效',held:'持有中',awaiting_inspection:'等待验仓',inspection_failed:'验仓未通过',completed:'退租完成',processing:'退款处理中',refunded_simulated:'退款已记录',requested_locally:'申请已保存',awaiting_advisor:'待顾问确认',saved_locally:'已保存，尚未发送',withdrawn:'已撤回',submitted_simulated:'已保存'};
