  const errors={PHONE_REQUIRED:'请先完成微信或短信验证后核对价格',ORDER_NOT_FOUND:'未找到这笔订单，请从订单列表进入',ACTIVE_ORDER_REQUIRED:'请在起租并完成身份验证、开始用仓后申请退租',PAID_ORDER_REQUIRED:'需要已付款订单才能办理此项服务',ORDER_EXPIRED:'待支付订单已过期，仓位和优惠券已释放，请重新选择',QUOTE_STALE:'金额或库存已变化，请重新核对',IDENTITY_REQUIRED:'请先完成身份验证',BEFORE_START:'尚未到起租日期，可先查看指引',ORDER_CLOSED:'该订单已退租',SELECT_TERM:'请选择1–60个月的整数租期',SELECT_DATE:'请选择有效日期',EMPTY_REQUIRED:'请确认计划取空物品后再申请验仓',EXIT_IN_PROGRESS:'退租申请办理中，暂不能续租或重复申请',INVALID_EXIT_STATE:'当前状态不能进行此项操作',INSPECTION_REQUIRED:'验仓完成后才可处理退款',INVOICE_FIELDS:'请填写发票抬头和有效邮箱',INVOICE_EXISTS:'该付款记录已经申请发票，请查看进度',INVALID_PAYMENT:'请选择有效的付款记录',TRANSPORT_FIELDS:'请填写运输地址并选择有效日期',ENTER_QUESTION:'请填写咨询内容',ENTER_PHONE:'请填写有效联系电话',ENTER_ADDRESS:'请填写完整用仓地址',LEAD_WITHDRAWN:'该需求已撤回',INVALID_ORDER_STATE:'当前订单状态不支持此操作'};
  function notify(t){$('notice').textContent=t;}
  function action(fn){try{const result=fn();persist();return result;}catch(e){persist();notify(errors[e.message]||'操作未完成，请检查填写内容');return null;}}
  function sheet(title,body){$('sheet-title').textContent=title;$('sheet-body').innerHTML=body;$('sheet').showModal();}
  function close(){$('sheet').close();if(state().auth.status==='pending'){core.resolvePhone('denied');persist();}}
  const phoneAuth=SIM_PHONE_AUTH.create({core,persist,onChange:()=>render(),onMessage:message=>notify(message)});
  function auth(){if(core.authorized()){notify('手机号已验证，有效会话内无需重复操作');return;}return phoneAuth.verify();}
  const orderLabel=value=>{const suffix=String(value||'').match(/[0-9]+$/)?.[0];if(suffix)return 'KL'+suffix.padStart(8,'0');return 'KL'+Array.from(String(value||'')).reduce((n,ch)=>(Math.imul(n,31)+ch.charCodeAt(0))>>>0,0).toString().padStart(10,'0').slice(-10);};
  function headerOrder(o){return '<p><b>'+esc(store(o.store_id)?.name)+'</b></p><p>'+esc(o.unit_ids.map(u=>unit(u)?.name).join(' + '))+'</p><p>'+esc(o.term_months)+'个月 · '+esc(o.start_date)+'起租</p><p class="small">'+esc('订单编号 '+orderLabel(o.id))+'</p>'+tag(o.status);}
  function profile(){const s=state(),phone=s.account&&s.account.phone?String(s.account.phone):'',maskNumber=x=>esc(String(x).replace(/(\d{3})\d{4}(\d{4})$/,'$1****$2'));return panel('账户与联系方式','<div class="account-profile-lines"><div><span>验证手机号</span><strong>'+(phone?maskNumber(phone):'尚未验证')+'</strong></div><div><span>联系手机号</span><strong>'+(s.contactPhone?maskNumber(s.contactPhone):'未填写')+'</strong></div></div><div class="button-row">'+button('contact','修改联系电话','','outline')+(core.authorized()?'':button('phone','验证手机号'))+'</div>');}
  function mine(){const s=state(),pending=s.orders.filter(o=>o.status==='pending').length,paid=s.orders.filter(o=>o.status==='paid_simulated').length;return panel('用仓服务','<p>待支付 '+pending+' 笔 · 已付款 '+paid+' 笔 · 有效需求 '+[...s.leads,...s.enterpriseLeads].filter(l=>l.status!=='withdrawn').length+' 条</p><div class="menu-grid">'+[['orders','我的订单'],['needs','我的需求'],['favorites','我的收藏'],['coupons','我的优惠券'],['invoice','发票与付款记录'],['transport','运输需求'],['referral','推荐有礼'],['messages','消息'],['support','联系顾问'],['brand','关于迷你考拉']].map(([v,t])=>link(v,t,'','')).join('')+'</div>')+panel('账户与联系方式','<p>'+esc(s.account?(core.authorized()?'已登录 · ':'登录已过期 · ')+s.account.phone.replace(/(\d{3})\d{4}(\d{4})$/,'$1****$2')+'（本地账户）':'尚未注册登录')+'</p><p>'+esc(s.contactPhone?'已填写 '+s.contactPhone:core.authorized()?'手机号已验证':'尚未提供联系方式')+'</p><div class="button-row">'+button('contact','填写或修改手机号','','outline')+button('phone',core.authorized()?'手机号已验证':'手机号验证','','outline')+'</div>')+panel('内部预览设置','<details class="settings"><summary>订单多状态样本与流程验证</summary><p>切换会清空本窗口的本地需求和订单。所有支付、验证、验仓、退款均为本地状态，不发送外部请求。</p><label for="seed-profile">选择状态</label><select id="seed-profile"><option value="pending">待支付</option><option value="identity">已付款待验证</option><option value="active">租赁中</option><option value="renew">已续租</option><option value="inspection">待验仓</option><option value="refunded">已退租并退款</option></select>'+button('seed','载入所选订单样本','','outline')+'</details>');}
  function orderList(){return panel('全部订单',state().orders.length?state().orders.slice().reverse().map(o=>'<article class="list-item">'+headerOrder(o)+'<div class="button-row">'+link('order','查看订单',o.id)+'</div></article>').join(''):empty('暂无订单，可先选择门店和仓位'));}
  function orderView(){const o=core.orderDetail(id),service=o.service;let body=headerOrder(o)+amounts(o);if(o.status==='pending')body+='<p class="small">待支付订单保留15分钟，支付前会再次核对仓位和金额。</p><div class="button-row">'+button('pay','继续支付',id)+button('cancelOrder','取消待支付订单',id,'outline')+'</div>';else if(o.status==='paid_simulated'){const used=service?.useStatus==='active';body+='<h3>'+ (service?.exit?statusName[service.exit.status]||'退租处理中':used?'租赁中':service?.identity==='verified'?'待入仓':'待完成身份验证')+'</h3><div class="menu-grid">'+[['identity','身份验证'],['access','入仓指引'],['renew','续租'],['exit','退租与验仓'],['deposit','押金进度'],['invoice','发票与付款记录'],['transport','运输需求'],['support','订单咨询']].map(([v,t])=>link(v,t,id,'')).join('')+'</div>';}else body+='<p>当前订单已结束；如需用仓，请重新核对可租方案。</p><a class="primary" href="index.html?page=QUICK">重新选仓</a>';return panel('订单详情',body);}
  function needs(){const s=state(),leads=[...s.leads,...s.enterpriseLeads];return panel('我的需求',leads.length?leads.slice().reverse().map(l=>'<article class="list-item"><h3>'+esc(l.type==='ENTERPRISE_REQUIREMENT'?'企业用仓需求':l.service_source==='estore'?'考拉E存咨询':l.type==='ADVISOR_CONSULTATION'?'顾问咨询需求':'个人用仓需求')+'</h3><p>'+esc(l.address||l.location||(l.type==='ADVISOR_CONSULTATION'?'未填写用仓地址（选填）':'地址待补充'))+'</p><p>'+esc(l.capacity_hint||(l.capacity_m3?l.capacity_m3+'m³':'容量待补充'))+' · '+esc(l.term_hint||(l.term_months?l.term_months+'个月':'租期待补充'))+'</p>'+(l.phone?'<p>联系电话：'+esc(l.phone.replace(/(\d{3})\d{4}(\d{4})$/,'$1****$2'))+'</p>':'')+tag(l.status)+(l.status!=='withdrawn'?'<div class="button-row">'+(l.type==='ENTERPRISE_REQUIREMENT'?'<a class="outline" href="business.html?lead='+encodeURIComponent(l.id)+'">补充企业资料</a>':'')+button('editLead','修改地址与备注',l.id,'outline')+button('withdraw','撤回需求',l.id,'outline')+'</div>':'')+'</article>').join(''):empty('暂无已保存需求'));}
  function favorites(){const ui=read('mk_visual_align_ui_v1')||{},stores=(ui.storeFavorites||[]).map(store).filter(Boolean),units=(ui.favorites||[]).map(unit).filter(Boolean);return panel('收藏的门店与仓位',stores.map(s=>'<p><a href="index.html?page=S02&store='+esc(s.id)+'">'+esc(s.name)+'</a></p>').join('')+units.map(u=>'<p><a href="index.html?page=S02&store='+esc(u.store_id)+'">'+esc(store(u.store_id).name+' · '+u.name)+'</a></p>').join('')+(!stores.length&&!units.length?empty('暂无收藏，可在门店详情收藏'):'') );}
